WITH base AS (SELECT *, SUBSTRING(location, 1, 2) AS location_prefix FROM departments WHERE location = 'Berlin' AND location = 'Tokyo'), departments_stats AS (SELECT CASE WHEN budget >= 3967000 THEN 'high' WHEN budget >= 774000 THEN 'mid' ELSE 'low' END AS budget_bucket, ROUND((100 * SUM(CASE WHEN location = 'Tokyo' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_tokyo, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(location))) AS location_values FROM base GROUP BY CASE WHEN budget >= 3967000 THEN 'high' WHEN budget >= 774000 THEN 'mid' ELSE 'low' END) SELECT * FROM departments_stats WHERE pct_tokyo < 50
